package com.group01.assessment.application.usecase;
import com.group01.assessment.application.result.AssessmentResultResult; import com.group01.assessment.domain.exception.AssessmentNotFoundException; import com.group01.assessment.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class GetAssessmentResultUseCase { private final AssessmentAttemptRepository attempts; private final AssessmentResultRepository results; public GetAssessmentResultUseCase(AssessmentAttemptRepository attempts,AssessmentResultRepository results){this.attempts=attempts;this.results=results;} @Transactional(readOnly=true) public AssessmentResultResult execute(UUID userId,UUID attemptId){attempts.findByIdAndUserId(attemptId,userId).orElseThrow(()->new AssessmentNotFoundException("Assessment attempt not found")); var r=results.findLatestByAttemptId(attemptId).orElseThrow(()->new AssessmentNotFoundException("Assessment result not found")); return new AssessmentResultResult(r.id(),r.attemptId(),r.resultVersion(),r.status(),r.overallBand(),r.completedAt());} }
